    r0 = min(r for r, c in hidden)
    r1 = max(r for r, c in hidden)
    c0 = min(c for r, c in hidden)
    c1 = max(c for r, c in hidden)
    H, W = r1 - r0 + 1, c1 - c0 + 1
    blocked = set(hidden)

    # Look for symmetries of the visible grid. The obscured patch is usually
    # recoverable from its corresponding location under one of these.
    transforms = [
        lambda r, c: (r, w - 1 - c),
        lambda r, c: (h - 1 - r, c),
        lambda r, c: (h - 1 - r, w - 1 - c),
    ]
    if h == w:
        transforms += [
            lambda r, c: (c, r),
            lambda r, c: (h - 1 - c, w - 1 - r),
            lambda r, c: (c, w - 1 - r),
            lambda r, c: (h - 1 - c, r),
        ]

    scored = []
    for fn in transforms:
        same = total = 0
        for r in range(h):
            for c in range(w):
                rr, cc = fn(r, c)
                if (r, c) in blocked or (rr, cc) in blocked:
                    continue
                same += grid[r][c] == grid[rr][cc]
                total += 1
        if total:
            scored.append((same / total, fn))
    scored.sort(key=lambda x: x[0], reverse=True)

    out = []
    for dr in range(H):
        row = []
        for dc in range(W):
            r, c = r0 + dr, c0 + dc
            votes = {}
            for score, fn in scored:
                rr, cc = fn(r, c)
                if 0 <= rr < h and 0 <= cc < w and (rr, cc) not in blocked:
                    votes[grid[rr][cc]] = votes.get(grid[rr][cc], 0) + score ** 4
            if votes:
                value = max(votes, key=votes.get)
            else:
                # Fallback: copy from the closest matching visible row.
                best = None
                for rr in range(h):
                    if rr == r:
                        continue
                    match = total = 0
                    for cc in range(w):
                        if cc in range(c0, c1 + 1) or grid[rr][cc] == 8:
                            continue
                        match += grid[r][cc] == grid[rr][cc]
                        total += 1
                    if total and (best is None or match / total > best[0]):
                        best = (match / total, rr)
                value = grid[best[1]][c] if best and grid[best[1]][c] != 8 else 0
            row.append(value)
        out.append(row)
    return out
